const data = msg.payload;

if (!data.measurement || !data.tags || !data.fields) {
    node.error("JSON inválido", msg);
    return null;
}

// --- SALIDA 1: Para InfluxDB (Line Protocol) ---
let lineProtocol = data.measurement;
const tagKeys = Object.keys(data.tags);
if (tagKeys.length > 0) {
    lineProtocol += "," + tagKeys.map(k => `${k}=${data.tags[k]}`).join(",");
}
const fieldKeys = Object.keys(data.fields);
const fieldValues = fieldKeys.map(k => {
    const v = data.fields[k];
    if (typeof v === 'number') return Number.isInteger(v) ? `${k}=${v}i` : `${k}=${v}`;
    else if (typeof v === 'boolean') return `${k}=${v}`;
    else return `${k}="${v}"`;
});
lineProtocol += " " + fieldValues.join(",");

const msgInflux = { payload: lineProtocol };

// --- SALIDA 2: JSON Original para Lógica de Seguridad ---
const msgLogic = { payload: data };

// Retornar array: [Salida 1, Salida 2]
return [msgInflux, msgLogic];

const data = msg.payload;
const eventCode = (data.fields.event_code || " ").toString().toUpperCase();
const deviceId = data.tags.device_id || "NODO_DESCONOCIDO";
let message = data.fields.message || eventCode;

// --- BONUS INGENIERO: Decodificar Hexadecimal a Texto ---
if (/^[0-9A-Fa-f]+$/.test(message) && message.length % 2 === 0) {
    let str = '';
    for (let i = 0; i < message.length; i += 2) {
        str += String.fromCharCode(parseInt(message.substr(i, 2), 16));
    }
    message = str.replace(/\0/g, '').trim();
}

// --- LÓGICA DE FILTRADO POR PREFIJOS ---
const esAlarma = eventCode.startsWith("ALRM") || 
                 eventCode.startsWith("MOV") || 
                 eventCode.startsWith("GAS") || 
                 eventCode.startsWith("DOOR") || 
                 eventCode.startsWith("SEIS") || 
                 eventCode.startsWith("SOS") || 
                 eventCode.startsWith("PANIC") || 
                 eventCode.startsWith("HUM");

if (esAlarma) {
    // Preparar payload para Gotify
    msg.payload = {
        title: ` Alarma: ${eventCode}`,
        message: `📍 Nodo: ${deviceId}\n📝 Detalle: ${message}\n Estado: ${data.fields.system_state || "N/A"}`,
        priority: 5
    };
    msg.headers = { "Content-Type": "application/json" };
    return msg;
}

return null;
